def diamonds(g):
    twos=[(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==2]
    ds=[]
    for t in twos:
        for d in ds:
            if t in d['cells']: break
        else:
            # floodfill
            cells=set([t]); st=[t]
            while st:
                r,c=st.pop()
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]==2 and (nr,nc) not in cells:
                            cells.add((nr,nc)); st.append((nr,nc))
            rs=[r for r,c in cells]; cs=[c for r,c in cells]
            ds.append({'cells':cells,'cr':(min(rs)+max(rs))/2,'cc':(min(cs)+max(cs))/2})
    return ds

def transform(g):
    g=[r[:] for r in g]; ds=diamonds(g)
    for i in range(len(ds)):
        for j in range(i+1,len(ds)):
            a,b=ds[i],ds[j]
            if a['cr']==b['cr']:
                r=int(a['cr']); cs=[c for d in(a,b) for r0,c in d['cells'] if r0==r]
                for c in range(min(cs)+1,max(cs)): g[r][c]=1
            if a['cc']==b['cc']:
                c=int(a['cc']); rs=[r for d in(a,b) for r0,c0 in d['cells'] if c0==c]
                for r in range(min(rs)+1,max(rs)): g[r][c]=1
    return g

